components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background: #5b9bd5;
  color: #ffffff;
  font-family: "IBM Plex Sans", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1;
  padding: 0.625rem 1.25rem;
  border: none;
  border-radius: 0.75rem;
  box-shadow: 0 1px 3px rgba(48,86,122,0.04), 0 1px 2px rgba(48,86,122,0.03);
  cursor: pointer;
  transition: background 0.2s, box-shadow 0.2s, transform 0.2s;
}
.ds-btn-primary:hover {
  background: #3f7db8;
  box-shadow: 0 4px 16px rgba(48,86,122,0.06), 0 2px 4px rgba(48,86,122,0.03);
  transform: translateY(-1px);
}
.ds-btn-primary:focus-visible {
  outline: 2px solid rgba(91,155,213,0.6);
  outline-offset: 2px;
}
.ds-btn-primary:active {
  background: #366596;
  transform: translateY(0);
}
.ds-btn-primary:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
}

.ds-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background: #f0f5fa;
  color: #30567a;
  font-family: "IBM Plex Sans", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1;
  padding: 0.625rem 1.25rem;
  border: 1px solid #e3eef7;
  border-radius: 0.75rem;
  cursor: pointer;
  transition: background 0.2s;
}
.ds-btn-secondary:hover {
  background: #e3eef7;
}
.ds-btn-secondary:focus-visible {
  outline: 2px solid rgba(91,155,213,0.6);
  outline-offset: 2px;
}
.ds-btn-secondary:active {
  background: #c7ddf0;
}
.ds-btn-secondary:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background: transparent;
  color: #3a5a78;
  font-family: "IBM Plex Sans", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1;
  padding: 0.5rem 0.75rem;
  border: none;
  border-radius: 0.75rem;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}
.ds-btn-ghost:hover {
  background: #f0f5fa;
  color: #30567a;
}
.ds-btn-ghost:focus-visible {
  outline: 2px solid rgba(91,155,213,0.6);
  outline-offset: 2px;
}
.ds-btn-ghost:active {
  background: #e3eef7;
}

.ds-card {
  background: #ffffff;
  border: 1px solid rgba(227,238,247,0.5);
  border-radius: 1rem;
  padding: 1.25rem;
  box-shadow: 0 1px 3px rgba(48,86,122,0.04), 0 1px 2px rgba(48,86,122,0.03);
  transition: box-shadow 0.3s, border-color 0.3s;
}
.ds-card:hover {
  box-shadow: 0 8px 30px rgba(48,86,122,0.08), 0 3px 8px rgba(48,86,122,0.04);
  border-color: rgba(199,221,240,0.6);
}
.ds-card-title {
  font-family: "IBM Plex Sans", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  color: #30567a;
  line-height: 1.375;
  margin: 0 0 0.25rem 0;
}
.ds-card-body {
  font-family: "IBM Plex Sans", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  font-size: 0.9375rem;
  font-weight: 400;
  color: #3a5a78;
  line-height: 1.625;
  margin: 0;
}

.ds-input {
  width: 100%;
  background: #f0f5fa;
  border: 1px solid rgba(199,221,240,0.6);
  border-radius: 0.75rem;
  padding: 0.625rem 1rem;
  font-family: "IBM Plex Sans", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  font-size: 0.875rem;
  color: #30567a;
  line-height: 1.5;
  transition: border-color 0.2s, background 0.2s, box-shadow 0.2s;
  box-sizing: border-box;
}
.ds-input::placeholder {
  color: #6b8aaa;
}
.ds-input:focus {
  outline: none;
  border-color: #5b9bd5;
  background: #ffffff;
  box-shadow: 0 0 0 4px rgba(91,155,213,0.08);
}
.ds-input:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;
  font-family: "IBM Plex Sans", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  font-size: 0.6875rem;
  font-weight: 500;
  line-height: 1;
}
.ds-badge-info {
  background: #f4f8fc;
  color: #3f7db8;
  border: 1px solid #e3eef7;
}

.ds-nav-link {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.375rem 0.75rem;
  border-radius: 0.5rem;
  font-family: "IBM Plex Sans", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  font-size: 0.75rem;
  font-weight: 500;
  color: #3a5a78;
  text-decoration: none;
  transition: color 0.2s, background 0.2s;
  cursor: pointer;
}
.ds-nav-link:hover {
  color: #30567a;
  background: #f0f5fa;
}
.ds-nav-link-active {
  background: #f4f8fc;
  color: #5b9bd5;
}
.ds-nav-link-active:hover {
  background: #f4f8fc;
  color: #5b9bd5;
}

.ds-skeleton {
  background: linear-gradient(90deg, #e3eef7 0%, #f0f5fa 50%, #e3eef7 100%);
  background-size: 200% 100%;
  border-radius: 0.5rem;
  animation: ds-shimmer 2s ease-in-out infinite;
}
@keyframes ds-shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}
